<?php
require dirname(__DIR__).'/includes/bootstrap.php'; require_permission('users.manage'); $bid=current_branch_id();
$templates=['customers'=>['full_name','phone','gender','email','address'],'products'=>['name','brand','barcode','buying_price','selling_price','minimum_stock'],'services'=>['name','category_id','duration_minutes','price'],'suppliers'=>['name','phone','email','address'],'staff'=>['full_name','phone','role_title','salary']];
if(isset($_GET['template']) && isset($templates[$_GET['template']])) csv_download($_GET['template'].'_template.csv',$templates[$_GET['template']],[]);
if($_SERVER['REQUEST_METHOD']==='POST'){ verify_csrf(); $type=$_POST['type']; try{ if(empty($_FILES['csv']['tmp_name'])) throw new RuntimeException('Upload a CSV file.'); $fh=fopen($_FILES['csv']['tmp_name'],'r'); $head=fgetcsv($fh); $count=0; while(($row=fgetcsv($fh))!==false){$d=array_combine($head,$row); if(!$d)continue; if($type==='customers' && !empty($d['full_name'])){q('INSERT INTO customers(branch_id,customer_no,full_name,phone,gender,email,address,status,created_at) VALUES(?,?,?,?,?,?,?,"active",NOW())',[$bid,'CUS-'.date('ymd').'-'.str_pad((string)((int)scalar('SELECT COUNT(*)+1 FROM customers')),4,'0',STR_PAD_LEFT),$d['full_name'],normalize_phone($d['phone']??''),$d['gender']?:null,$d['email']??'',$d['address']??'']);$count++;}
 elseif($type==='products'&&!empty($d['name'])){q('INSERT INTO products(branch_id,name,brand,barcode,buying_price,selling_price,minimum_stock,status,created_at) VALUES(?,?,?,?,?,?,?,"active",NOW())',[$bid,$d['name'],$d['brand']??'',$d['barcode']??'',(float)($d['buying_price']??0),(float)($d['selling_price']??0),(float)($d['minimum_stock']??0)]);$pid=(int)db()->lastInsertId();ensure_stock_level($bid,$pid);$count++;}
 elseif($type==='services'&&!empty($d['name'])){q('INSERT INTO services(branch_id,category_id,name,duration_minutes,price,status,created_at) VALUES(?,?,?,?,?,"active",NOW())',[$bid,(int)($d['category_id']??0)?:null,$d['name'],(int)($d['duration_minutes']??30),(float)($d['price']??0)]);$count++;}
 elseif($type==='suppliers'&&!empty($d['name'])){q('INSERT INTO suppliers(branch_id,name,phone,email,address,status,created_at) VALUES(?,?,?,?,?,"active",NOW())',[$bid,$d['name'],$d['phone']??'',$d['email']??'',$d['address']??'']);$count++;}
 elseif($type==='staff'&&!empty($d['full_name'])){q('INSERT INTO staff(branch_id,full_name,phone,role_title,salary,status,created_at) VALUES(?,?,?,?,?,"active",NOW())',[$bid,$d['full_name'],$d['phone']??'',$d['role_title']??'',(float)($d['salary']??0)]);$count++;}}
 flash('success',$count.' records imported.');}catch(Throwable $e){flash('error',$e->getMessage());} redirect('modules/imports.php');}
$title='Import / Export'; $subtitle='Import customers, products, services, suppliers and staff from Excel/CSV; export templates and reports.'; include dirname(__DIR__).'/includes/header.php';?><section class="card"><h2>Import CSV</h2><form method="post" enctype="multipart/form-data"><?=csrf_field()?><div class="form-grid"><div class="form-group"><label>Type</label><select name="type"><?php foreach($templates as $k=>$v):?><option value="<?=e($k)?>"><?=e(ucfirst($k))?></option><?php endforeach;?></select></div><div class="form-group"><label>CSV File</label><input type="file" name="csv" accept=".csv" required></div></div><button class="btn">Import</button></form></section><section class="card"><h2>Download CSV Templates</h2><?php foreach($templates as $k=>$v):?><a class="btn secondary" href="?template=<?=e($k)?>"><?=e(ucfirst($k))?> Template</a> <?php endforeach;?></section><?php include dirname(__DIR__).'/includes/footer.php'; ?>